SELECT sum(mdr_inr) mdr, sum(net_inr) net, sum(gross_inr) gross, sum(refunds_inr) refunds
FROM payments.upi_settlements
WHERE settlement_date >= '2026-06-01' AND settlement_date < '2026-07-01';

SELECT sku, status, count(*) FROM store.shelf_audits
WHERE audit_ts >= '2026-06-01' AND audit_ts < '2026-07-01'
GROUP BY sku, status ORDER BY sku, status;

SELECT (SELECT sum(wo.units*p.cost_inr) FROM store.write_offs wo JOIN store.products p ON p.sku=wo.sku WHERE wo.date >= '2026-06-01' AND wo.date < '2026-07-01') june_writeoff_value,
       (SELECT round(sum(b.book_on_hand_close*p.cost_inr),0) FROM store.inventory_book b JOIN store.products p ON p.sku=b.sku WHERE b.date=(SELECT max(date) FROM store.inventory_book)) stock_value_latest,
       (SELECT max(date)::text FROM store.inventory_book) stock_date;

SELECT date, units_sold, revenue_inr, round(revenue_inr/units_sold,2) implied_price
FROM store.daily_sales WHERE sku='ATTA-WW-5KG' AND date >= '2026-06-01'
ORDER BY date LIMIT 10;

SELECT date, units_sold, revenue_inr
FROM store.daily_sales WHERE sku='ATTA-WW-5KG' AND date >= '2026-06-01'
ORDER BY date;

SELECT kind, count(*) FROM payments.customer_complaints
WHERE complaint_ts >= '2026-06-01' AND complaint_ts < '2026-07-01'
GROUP BY kind;

SELECT audit_ts::text, sku, status FROM store.shelf_audits
WHERE audit_ts >= '2026-06-01' AND audit_ts < '2026-07-01' AND status='empty'
ORDER BY audit_ts;

SELECT count(*) n, min(created_ts)::text, max(created_ts)::text, sum(units) units, sum(cases) cases
FROM store.store_orders
WHERE created_ts >= '2026-06-01' AND created_ts < '2026-07-01';

SELECT count(*) FROM information_schema.columns
WHERE table_schema IN ('store','warehouse','payments')
  AND (column_name ~* 'supplier|vendor|payable|receivable|credit_days|terms|invoice' OR table_name ~* 'supplier|vendor|payable');
